import{z as i,x as s,o as A,c as d,q as l,j as r,D as a,d as e,s as n,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Agent 轨迹合成","description":"","frontmatter":{"title":"Agent 轨迹合成","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-agent-traj.md","filePath":"llm/synthetic-agent-traj.md","lastUpdated":1791413859000}'),m={name:"llm/synthetic-agent-traj.md"};function D(p,E,h,c,C,f){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="agent-轨迹合成" tabindex="-1">Agent 轨迹合成 <a class="header-anchor" href="#agent-轨迹合成" aria-label="Permalink to &quot;Agent 轨迹合成&quot;">​</a></h1><div class="epigraph"><p>轨迹合成的铁律：观测必须来自环境返回，不能来自模型的想象——脑补出来的观测，会教出一个相信幻觉的策略。</p><footer>—— 据 Schick 等 Toolformer；Gulcehre 等 ReST；Zeng 等 AgentTuning 整理</footer></div><p><a href="/llm/synthetic-multiturn">上一课</a>让用户模拟器第一次把「环境」引进了合成；本课把环境换成可执行系统：工具、沙箱、任务与结局。Agent 轨迹是一条「思考—行动—观测」序列，它的合成质量几乎完全由环境侧决定，模型侧反而自由。<a href="/llm/tool-sandbox">工具沙箱</a>与 <a href="/llm/tool-call-sft">function calling 训练</a>已立基建，本课写数据线：任务从哪来、轨迹怎么采、结局怎么判、什么该剪掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>轨迹合成的缺口在任务侧与观测侧。任务侧：工具组合空间指数大，从工具文档自动造任务（「用这三个 API 完成某事」）命中率低，多数生成任务要么不可解要么无判据——任务有效率是这条线的第一瓶颈。观测侧最大的陷阱是「脑补观测」：让教师模型一口气写完整条轨迹（包括工具返回），生成便宜且通顺，但观测是想象——模型从此学会在真实运行里也想象工具输出，错误在多步之后爆炸。结局侧：以任务成功过滤轨迹给了强真值，但纯成功过滤会把分布压向「易任务加保守策略」，失败信息全部丢弃。<span class="marginnote">术语翻译：「轨迹」就是一次任务从头到尾的逐步记录——模型想了什么（思考）、做了什么（调用哪个工具、什么参数）、环境回了什么（观测），像行车记录仪的完整录像，而不是只记起点和终点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四段线。任务段：以环境能力为纲造任务——枚举工具与参数组合，按组合模板生成任务描述与初始状态，成功率试采定难度，不可解或无判据的任务在源头淘汰；<a href="/llm/toolformer">Toolformer</a>式的自监督（用「插入调用是否降低未来损失」筛调用点）适合无明确任务的工具熟悉数据。采集段：策略在沙箱里真跑，观测取环境返回原文，超时与异常原样保留——它们本身就是训练信号；<a href="/llm/rft-data-loop">RFT 数据循环</a>的「采样、过滤、回灌」是骨架。结局段：成功按可判定的终态判（文件存在、测试通过、答案核对），不靠模型自评；失败轨迹不整条丢弃，剪出「错误步加恢复步」的对子入库。整形段：剪冗余重试与循环步，保留「探索—失败—调整—成功」的结构——这正是多步能力的学习对象。</p>',7)),(A(),r(o,null,{default:a(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOOLS%5B%22%E5%B7%A5%E5%85%B7%E4%B8%8E%E5%8F%82%E6%95%B0%E7%BB%84%E5%90%88%22%5D%20--%3E%20TASK%5B%22%E4%BB%BB%E5%8A%A1%E7%94%9F%E6%88%90%E4%B8%8E%E5%88%9D%E6%80%81%22%5D%0A%20%20TASK%20--%3E%20VALID%7B%22%E5%8F%AF%E8%A7%A3%E4%B8%94%E6%9C%89%E5%88%A4%E6%8D%AE%EF%BC%9F%22%7D%0A%20%20VALID%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E6%BA%90%E5%A4%B4%E6%B7%98%E6%B1%B0%22%5D%0A%20%20VALID%20--%3E%7C%E6%98%AF%7C%20RUN%5B%22%E6%B2%99%E7%AE%B1%E9%87%87%E9%9B%86%EF%BC%9A%E6%80%9D%E8%80%83-%E8%A1%8C%E5%8A%A8-%E8%A7%82%E6%B5%8B%22%5D%0A%20%20RUN%20--%3E%20OBS%7B%22%E8%A7%82%E6%B5%8B%E6%9D%A5%E8%87%AA%E7%8E%AF%E5%A2%83%E8%BF%94%E5%9B%9E%EF%BC%9F%22%7D%0A%20%20OBS%20--%3E%7C%E8%84%91%E8%A1%A5%7C%20REJ%5B%22%E6%95%B4%E6%9D%A1%E6%8B%92%E7%BB%9D%22%5D%0A%20%20OBS%20--%3E%7C%E7%9C%9F%E5%AE%9E%7C%20END%7B%22%E7%BB%88%E6%80%81%E5%88%A4%E5%AE%9A%22%7D%0A%20%20END%20--%3E%7C%E6%88%90%E5%8A%9F%7C%20KEEP%5B%22%E5%85%A5%E5%BA%93%EF%BC%9A%E6%88%90%E5%8A%9F%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20END%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20PAIR%5B%22%E5%89%AA%E9%94%99%E8%AF%AF%E6%AD%A5%E4%B8%8E%E6%81%A2%E5%A4%8D%E6%AD%A5%E6%88%90%E5%AF%B9%E5%85%A5%E5%BA%93%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"结局过滤的机制价值与代码域一致——程序级拦截率撑起放量；它的新增代价是选择压力：只留成功轨迹时，训练分布向策略已会的区域收缩，探索行为被系统性淘汰。剪「失败加恢复」对子是直接的解法：保留失败的信息，去掉失败的噪声。环境与真实工具的差距是本课版本的 sim-to-real：沙箱里的 API 无限耐心、无并发、无限额，模型学到的调用习惯——不等结果、不重试、忽略限流——在真实环境里全部失灵；缓解不是造完美环境，而是在环境里显式注入这些「不配合」：限速、部分失败、格式漂移。任务有效率的瓶颈没有银弹：模板命中率随任务复杂度骤降，复杂任务的合成通常退回「真实种子加教师扩展」，纯自动造复杂任务仍是开放问题。",-1)),(A(),r(o,null,{default:a(()=>[n(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%BA%AF%E6%88%90%E5%8A%9F%E8%BF%87%E6%BB%A4%22%5D%20--%3E%20C1%5B%22%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%E6%94%B6%E7%BC%A9%E5%88%B0%E5%B7%B2%E4%BC%9A%E5%8C%BA%E5%9F%9F%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%8E%A2%E7%B4%A2%E8%A1%8C%E4%B8%BA%E8%A2%AB%E6%B7%98%E6%B1%B0%2C%20%E9%9A%BE%E4%BB%BB%E5%8A%A1%E6%B0%B8%E8%BF%9C%E5%AD%A6%E4%B8%8D%E4%BC%9A%22%5D%0A%20%20P%5B%22%E5%A4%B1%E8%B4%A5%E8%BD%A8%E8%BF%B9%E5%89%AA%E6%88%90%E9%94%99%E8%AF%AF-%E6%81%A2%E5%A4%8D%E5%AF%B9%22%5D%20--%3E%20K1%5B%22%E5%A4%B1%E8%B4%A5%E7%9A%84%E4%BF%A1%E6%81%AF%E7%95%99%E4%B8%8B%2C%20%E5%99%AA%E5%A3%B0%E5%8E%BB%E6%8E%89%22%5D%0A%20%20K1%20--%3E%20K2%5B%22%E5%88%86%E5%B8%83%E4%B8%8D%E6%94%B6%E7%BC%A9%2C%20%E6%81%A2%E5%A4%8D%E7%AD%96%E7%95%A5%E6%88%90%E4%B8%BA%E5%AD%A6%E4%B9%A0%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">sim-to-real 的直觉类比：沙箱像永远配合的陪练——秒回、不超时、从不限流；模型学出的「发了调用就有结果」习惯，在真实 API 的限速、超时、格式漂移面前全部失灵。解法不是造完美环境，而是故意让陪练不配合。</span></p><p><span class="marginnote">Toolformer 的筛选信号是「调用点插入后，未来 token 的损失是否下降」——不需要环境真值就能找到值得调工具的位置。有沙箱之后的成功率过滤更强，但两种信号覆盖不同：前者找「哪里该调」，后者判「最后成没成」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>结局判据只覆盖可形式化的任务；「用户体验好」这类终态无法程序判定，轨迹质量退回裁判与人审。采集成本随步数与环境调用次数放大，复杂任务的轨迹单条成本可能超过一次训练迭代，配比时要算账。轨迹数据的时效性强：工具 API 改版后，旧轨迹教的是过时接口，任务库要带环境版本号，随环境升级重采。本课只写单 agent 单任务的合成，多 agent 协作与环境编排是相邻课程的议题。<span class="marginnote">为什么重要：不带环境版本号时，API 从 v1 升到 v2 后旧轨迹还在教 v1 的参数名，模型持续输出已废弃的调用格式——这种退化在平均分里几乎看不出来，要用「格式有效率」单独监控才暴露。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任务从工具组合造，源头淘汰不可解无判据；任务有效率是第一瓶颈。</li><li>观测必须取环境返回原文，脑补轨迹整条拒绝。</li><li>成功轨迹入库，失败剪成错误-恢复对；纯成功过滤收缩探索分布。</li><li>环境要主动注入不配合：限速、部分失败、格式漂移，防 sim-to-real 失灵。</li><li>任务库带环境版本号，API 改版重采。</li><li>出处：Schick 等 Toolformer 2023；Gulcehre 等 ReST 2023；Zeng 等 AgentTuning 2023。</li></ul>',6))])}const u=i(m,[["render",D]]);export{g as __pageData,u as default};
